  capDetectorClassicName: ["shelf geometry", "선반 형태 분석", "货架几何", "棚の形状", "geometría del estante", "géométrie du rayon"],
  capDetectorVlmName: ["vision model boxes", "비전 모델 박스", "视觉模型框选", "ビジョンモデルの枠", "cajas del modelo de visión", "cadres du modèle de vision"],
  capReadWith: ["Read products with", "상품 읽기 방식", "商品识别模型", "商品の読み取り方法", "Leer productos con", "Lire les produits avec"],
  capDontRead: ["Don't read (typical prices)", "읽지 않음 (평균 가격 사용)", "不识别（使用常见价格）", "読み取らない（標準価格）", "No leer (precios típicos)", "Ne pas lire (prix habituels)"],
  capSavedModel: ["Saved model: {model}", "저장된 모델: {model}", "已保存的模型：{model}", "保存済みモデル：{model}", "Modelo guardado: {model}", "Modèle enregistré : {model}"],
