  capOrderSpendBreakdown: [" · goods {goods} · delivery {delivery} · unspent {unspent}", " · 상품 {goods} · 배송 {delivery} · 잔액 {unspent}", " · 商品 {goods} · 配送 {delivery} · 剩余 {unspent}", " · 商品 {goods} · 配送 {delivery} · 残額 {unspent}", " · productos {goods} · envío {delivery} · sin gastar {unspent}", " · marchandises {goods} · livraison {delivery} · non dépensé {unspent}"],
