  mkTimingDiff: ["B-minus-A mean time: {value}", "B − A 평균 시간: {value}", "B 减 A 的平均用时：{value}", "B − A の平均時間：{value}", "Tiempo medio B menos A: {value}", "Temps moyen B moins A : {value}"],
