  mkTimingBlock: ["{block}: {timed} / {planned} timed", "{block}: {planned}건 중 {timed}건 측정", "{block}：已计时 {timed} / {planned}", "{block}：{planned} 件中 {timed} 件を計時", "{block}: {timed} / {planned} medidos", "{block} : {timed} / {planned} chronométrées"],
  mkTimingRetain: ["Review is not saved; retain the audit CSV with your source records.", "검토 결과는 저장되지 않으니 감사 CSV를 원본 기록과 함께 보관하세요.", "核对结果不会保存；请将审计 CSV 与原始记录一起保留。", "確認結果は保存されません。監査 CSV を元の記録と一緒に保管してください。", "La revisión no se guarda; conserva el CSV de auditoría con tus registros de origen.", "La vérification n’est pas enregistrée ; conservez le CSV d’audit avec vos registres sources."],
  mkTimingExport: ["Export staff time audit CSV", "직원 시간 감사 CSV 내보내기", "导出店员用时审计 CSV", "スタッフ時間の監査 CSV を書き出す", "Exportar CSV de auditoría del tiempo del personal", "Exporter le CSV d’audit du temps du personnel"],
  mkTimingMethod: ["Timing method and limitations", "시간 측정 방법과 한계", "计时方法与局限", "計時の手法と限界", "Método de medición y limitaciones", "Méthode de chronométrage et limites"],
