  mkColHigherLowerEqual: ["Higher / lower / equal", "높음 / 낮음 / 같음", "更高 / 更低 / 相同", "高い / 安い / 同じ", "Mayor / menor / igual", "Plus haut / plus bas / égal"],
  mkColPositiveSum: ["Positive sum", "양수 합계", "正值合计", "プラスの合計", "Suma positiva", "Somme positive"],
  mkColNegativeSum: ["Negative sum", "음수 합계", "负值合计", "マイナスの合計", "Suma negativa", "Somme négative"],
